{"sql":"WITH nl AS (
  SELECT invoice FROM order_lines WHERE country='Netherlands' AND line_type='销售' AND order_date BETWEEN DATE '2011-01-01' AND DATE '2011-12-09' GROUP BY invoice
)
SELECT count(*) AS invoices_in_multiple_countries
FROM (SELECT DISTINCT l.invoice FROM order_lines l JOIN nl ON l.invoice=nl.invoice) t
WHERE t.invoice IN (SELECT invoice FROM order_lines WHERE invoice IN (SELECT invoice FROM nl) GROUP BY invoice HAVING count(DISTINCT country)>1)","purpose":"检查 Netherlands 发票是否同一发票包含其他国家/取消行的行数，以确认汇总口径"}
